"""Additive holonomy: detecting and quantifying impossible depth figures."""
from __future__ import annotations
from typing import List, Optional


def holonomy(t: List[float]) -> float:
    """Total additive increment accumulated once around the cyclic figure."""
    return sum(t)


def is_realizable(t: List[float], tol: float = 1e-12) -> bool:
    """A figure is realizable iff its holonomy vanishes."""
    return abs(holonomy(t)) <= tol


def reconstruct_gauge(t: List[float]) -> Optional[List[float]]:
    """Partial-sum height field h with h[i+1]-h[i]=t[i], or None if impossible."""
    if not is_realizable(t):
        return None
    h, running = [0.0] * len(t), 0.0
    for i, ti in enumerate(t):
        h[i] = running
        running += ti
    return h


if __name__ == "__main__":
    print("Penrose triangle [1,1,1]: holonomy =", holonomy([1, 1, 1]),
          "-> impossible:", not is_realizable([1, 1, 1]))
    print("Balanced figure [1,2,-3]: holonomy =", holonomy([1, 2, -3]),
          "-> gauge:", reconstruct_gauge([1, 2, -3]))

