function MONODROMY(t[0..n-1], mul, one):
    acc <- one
    for i in 0..n-1: acc <- mul(acc, t[i])
    return acc

function IS_REALIZABLE(t, mul, one, eq):
    return eq(MONODROMY(t, mul, one), one)

function FIND_IMPOSSIBILITY_WITNESS(t[0..n-1]):
    running <- 0
    for i in 0..n-1:
        partial[i] <- running
        running <- running + t[i]
    H <- running                               # = holonomy
    realizable <- (|H| <= tol)
    return (realizable, H, partial)
